import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 8
    fallback_columns = [
        "checked_at",
        "host",
        "selected_url",
        "final_url",
        "http_status",
        "content_type",
        "sources",
        "error",
    ]

    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"')
    records = []
    try:
        records = list(reader)
    except csv.Error:
        # The non-strict reader handles most malformed records; retain records
        # already parsed if an unusually malformed record still raises.
        pass

    records = [
        [str(value) for value in row]
        for row in records
        if row and any(value != "" for value in row)
    ]

    def normalized(value):
        return value.strip().lstrip("\ufeff").lower()

    header_index = None
    for index, row in enumerate(records):
        fields = [normalized(value) for value in row]
        if len(fields) >= 2 and fields[0] == "checked_at" and fields[1] == "host":
            header_index = index
            break

    if header_index is None:
        timestamp = re.compile(r"^\d{4}-\d{2}-\d{2}[T ]")
        for index, row in enumerate(records):
            if len(row) < expected_width or timestamp.match(row[0].strip()):
                continue
            fields = [normalized(value) for value in row[:expected_width]]
            identifier_fields = sum(
                bool(re.fullmatch(r"[a-z_][a-z0-9_]*", value))
                for value in fields
            )
            if identifier_fields >= 6:
                header_index = index
                break

    if header_index is None:
        columns = fallback_columns
        data_records = records
    else:
        columns = [value.strip().lstrip("\ufeff") for value in records[header_index]]
        data_records = records[header_index + 1:]

    width = len(columns) or expected_width
    if width < expected_width:
        columns.extend(f"column_{i + 1}" for i in range(width, expected_width))
        width = expected_width

    rows = []
    for record in data_records:
        row = list(record)
        if len(row) > width:
            row = row[:width - 1] + [",".join(row[width - 1:])]
        elif len(row) < width:
            row.extend([""] * (width - len(row)))
        rows.append(row)

    return {"columns": columns, "rows": rows}
